def solve_langford(n):
    """More systematic backtracking"""
    length = 2 * n
    seq = [0] * length

    placed = [False] * (n + 1)

    def backtrack(pos):
        if pos == length:
            return True

        if seq[pos] != 0:
            return backtrack(pos + 1)

        for v in range(1, n + 1):
            if not placed[v]:
                second_pos = pos + v + 1
                if second_pos < length and seq[second_pos] == 0:
                    seq[pos] = v
                    seq[second_pos] = v
                    placed[v] = True
                    if backtrack(pos + 1):
                        return True
                    seq[pos] = 0
                    seq[second_pos] = 0
                    placed[v] = False
        return False

    if backtrack(0):
        return seq
    return None

# Test for various n
for n in [3, 4, 5, 6, 7]:
    r = solve_langford(n)
    print(f"n={n}: {'SAT' if r else 'UNSAT'} (n mod 4 = {n % 4}), solution: {r}")
